import{B,C,read,path,pulse}from'../ten-utils.js';import{equivalentResistance,fmt10}from'../ten-math.js';
export default({g,p,extra,t})=>{let m=extra.mode??0,k=p[0],pts=[[-1,-.6,0],[1,-.6,0],[1,.6,0],[-1,.6,0],[-1,-.6,0]];path(g,pts);if(k>0)pulse(g,pts,t*(m===0?k/6:1),C.gold);g.box(0,-.6,0,.4,.12,.1,C.gold);g.line([-.15,.4,0],[-.15,.8,0],C.blue,3);g.line([.1,.5,0],[.1,.7,0],C.blue,3);
if(m===0){g.text(0,-.95,0,'R = 6 Ω');g.plot({title:B('Ohm’s law: V versus I','ओम का नियम: I के साथ V'),xMax:2,yMin:0,yMax:12,points:[[0,0],[2,12]],marker:[k/6,k]});return[read('Voltage V','विभवांतर V',k,'V'),read('Current I = V / R','धारा I = V / R',fmt10(k/6),'A'),read('Resistance','प्रतिरोध',6,'Ω')]}
if(m===1){let parallel=extra.topology===1,r=equivalentResistance(6,k,parallel);if(parallel){path(g,[[-.7,-.6,0],[-.7,0,0],[.7,0,0],[.7,-.6,0]]);g.box(0,0,0,.3,.1,.1,C.pink)}else g.box(1,0,0,.1,.25,.1,C.pink);return[read('Connection','संयोजन',parallel?B('Parallel','पार्श्वक्रम'):B('Series','श्रेणीक्रम')),read('Equivalent resistance','तुल्य प्रतिरोध',fmt10(r),'Ω'),read('Total current at 12 V','12 V पर कुल धारा',fmt10(12/r),'A')]}
for(let i=0;i<Math.round(k*k);i++)g.sphere(-.4+(i%7)*.14,-.65-Math.floor(i/7)*.12,0,.035,C.pink);return[read('Power P = I²R','शक्ति P = I²R',fmt10(k*k*5),'W'),read('Heat Q = I²Rt','ऊष्मा Q = I²Rt',fmt10(k*k*5*60),'J'),read('Fixed resistance and time','नियत प्रतिरोध और समय','5 Ω; 60 s')]};
